### What is the Sudoku Solver Problem?

Given a partially filled 9x9 Sudoku board, fill every empty cell so that each row, column, and 3x3 box contains the digits 1 through 9 exactly once. The board is represented as a 2D character array where '.' marks empty cells.

At National Bank of India, Pankaj built a tool that automatically completes a reconciliation grid where each row, column, and sub-block must contain each transaction code exactly once.

```java
package com.bank.service;

public class SudokuSolver {
    public static boolean solve(char[][] board) {
        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                if (board[r][c] == '.') {
                    for (char d = '1'; d <= '9'; d++) {
                        if (isValid(board, r, c, d)) {
                            board[r][c] = d;
                            if (solve(board)) return true;
                            board[r][c] = '.';  // backtrack
                        }
                    }
                    return false;  // no digit works: trigger backtracking
                }
            }
        }
        return true;  // no empty cells: solved
    }

    private static boolean isValid(char[][] board, int row, int col, char digit) {
        int boxRow = (row / 3) * 3;
        int boxCol = (col / 3) * 3;
        for (int i = 0; i < 9; i++) {
            if (board[row][i] == digit) return false;       // row check
            if (board[i][col] == digit) return false;       // column check
            if (board[boxRow + i / 3][boxCol + i % 3] == digit) return false;  // box check
        }
        return true;
    }

    public static void main(String[] args) {
        char[][] board = {
            {'5','3','.','.','7','.','.','.','.'},
            {'6','.','.','1','9','5','.','.','.'},
            {'.','9','8','.','.','.','.','6','.'},
            {'8','.','.','.','6','.','.','.','3'},
            {'4','.','.','8','.','3','.','.','1'},
            {'7','.','.','.','2','.','.','.','6'},
            {'.','6','.','.','.','.','2','8','.'},
            {'.','.','.','4','1','9','.','.','5'},
            {'.','.','.','.','8','.','.','7','9'}
        };
        if (solve(board)) {
            System.out.println("Solved:");
            printBoard(board);
        }
    }

    private static void printBoard(char[][] board) {
        for (char[] row : board) {
            System.out.println(new String(row));
        }
    }
}
```

